    def is_leap_year(year):
        """Check if a year is a leap year."""
        if year % 400 == 0:
            return True
        if year % 100 == 0:
            return False
        if year % 4 == 0:
            return True
        return False

    def days_in_month(year, month):
        """Return the number of days in a given month of a given year."""
        if month in [1, 3, 5, 7, 8, 10, 12]:
            return 31
        elif month in [4, 6, 9, 11]:
            return 30
        elif month == 2:
            return 29 if is_leap_year(year) else 28

    # Parse the input date
    year, month, day = map(int, date_str.split('-'))

    # Add n days
    if n >= 0:
        while n > 0:
            days_remaining_in_month = days_in_month(year, month) - day
            if n <= days_remaining_in_month:
                day += n
                n = 0
            else:
                n -= (days_remaining_in_month + 1)
                day = 1
                month += 1
                if month > 12:
                    month = 1
                    year += 1
    else:
        # n is negative, subtract days
        while n < 0:
            if day > 1:
                days_to_subtract = min(-n, day - 1)
                day += n  # n is negative, so this subtracts
                n = 0
            else:
                # Go to previous month
                month -= 1
                if month < 1:
                    month = 12
                    year -= 1
                n += day  # n is negative, so this adds (reduces the negative amount)
                day = days_in_month(year, month)

    # Format the result
    return f"{year:04d}-{month:02d}-{day:02d}""}

