    """add_days('2026-01-31', 3) == '2026-02-03'."""
    year, month, day = map(int, date_str.split('-'))

    # Convert date to days since epoch (using a simple day count)
    # We'll use a helper to convert to/from ordinal day numbers

    def is_leap(y):
        return (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)

    def days_in_month(y, m):
        if m in (1, 3, 5, 7, 8, 10, 12):
            return 31
        elif m in (4, 6, 9, 11):
            return 30
        elif m == 2:
            return 29 if is_leap(y) else 28

    def to_ordinal(y, m, d):
        """Convert date to ordinal (days since 0001-01-01)."""
        total = 0
        for yy in range(1, y):
            total += 366 if is_leap(yy) else 365
        for mm in range(1, m):
            total += days_in_month(y, mm)
        total += d
        return total

    def from_ordinal(ordinal):
        """Convert ordinal back to (year, month, day)."""
        y = 1
        while True:
            year_days = 366 if is_leap(y) else 365
            if ordinal <= year_days:
                break
            ordinal -= year_days
            y += 1

        m = 1
        while True:
            month_days = days_in_month(y, m)
            if ordinal <= month_days:
                break
            ordinal -= month_days
            m += 1

        return y, m, ordinal

    ordinal = to_ordinal(year, month, day)
    new_ordinal = ordinal + n
    new_year, new_month, new_day = from_ordinal(new_ordinal)

    return f"{new_year:04d}-{new_month:02d}-{new_day:02d}""}

