        return (y % 4 == 0) and (y % 100 != 0 or y % 400 == 0)

    def days_in_month(y, m):
        if m in (1, 3, 5, 7, 8, 10, 12):
            return 31
        elif m in (4, 6, 9, 11):
            return 30
        elif m == 2:
            return 29 if is_leap(y) else 28

    # Convert to a day count (days since 0001-01-01), add n, then convert back.
    # First, convert the given date to an ordinal.
    def date_to_ordinal(y, m, d):
        # Days from complete years
        total = 0
        for yy in range(1, y):
            total += 366 if is_leap(yy) else 365
        # Days from complete months in current year
        for mm in range(1, m):
            total += days_in_month(y, mm)
        # Days in current month
        total += d
        return total

    def ordinal_to_date(ord_):
        # Find year
        y = 1
        while True:
            year_days = 366 if is_leap(y) else 365
            if ord_ <= year_days:
                break
            ord_ -= year_days
            y += 1
        # Find month
        m = 1
        while True:
            month_days = days_in_month(y, m)
            if ord_ <= month_days:
                break
            ord_ -= month_days
            m += 1
        d = ord_
        return y, m, d

    ordinal = date_to_ordinal(year, month, day) + n
    y, m, d = ordinal_to_date(ordinal)
    return f"{y:04d}-{m:02d}-{d:02d}"
